_IMPI_WORKER_CTX: dict[str, object] = {}
_QP_LORENTZIAN_CV_WORKER_CTX: dict[str, object] = {}


def _compute_inline_control_scan(
    omega_grid: np.ndarray,
    p_grid: np.ndarray,
    eps_grid: np.ndarray,
    aup_grid: np.ndarray,
    control_up_grid: np.ndarray,
    full_slice_provider,
    control_slice_provider,
    *,
    eps_integration_mode: str,
    p_integration_mode: str,
    p_split_points: np.ndarray | None,
    p_gl_n: int,
) -> tuple[dict[str, np.ndarray], float]:
    """Integrate A*A - A0*A0 on one shared quadrature grid."""
    omega = np.asarray(omega_grid, dtype=float)
    ones = np.ones_like(np.asarray(aup_grid, dtype=float))
    thermal_raw = np.zeros(omega.size, dtype=float)
    no_thermal_raw = np.zeros(omega.size, dtype=float)
    medium_raw = np.zeros(omega.size, dtype=float)
    support_accum = 0.0

    for io, omega_value in enumerate(omega):
        full_down, full_support = full_slice_provider(int(io), float(omega_value))
        control_down, _ = control_slice_provider(int(io), float(omega_value))
        product_residual = (
            np.asarray(aup_grid, dtype=float) * np.asarray(full_down, dtype=float)
            - np.asarray(control_up_grid, dtype=float)
            * np.asarray(control_down, dtype=float)
        )
        support_accum += float(np.mean(np.asarray(full_support, dtype=float)))
        values = compute_impi_raw_totals_for_slice(
            float(omega_value),
            p_grid,
            eps_grid,
            product_residual,
            ones,
            eps_integration_mode=eps_integration_mode,
            p_integration_mode=p_integration_mode,
            p_split_points=p_split_points,
            p_gl_n=int(p_gl_n),
        )
        thermal_raw[io], no_thermal_raw[io], medium_raw[io] = values

    return (
        finalize_impi_scan(
            omega,
            thermal_raw,
            no_thermal_raw,
            medium_raw,
        ),
        support_accum / max(1, omega.size),
    )


def _env_enabled(name: str, default: str = "0") -> bool:
    return str(os.environ.get(name, default)).strip().lower() not in {
        "", "0", "false", "no", "off"
    }


def _load_sigma_rebuild_fields(
    path: Path,
) -> tuple[np.ndarray, np.ndarray, float, float]:
    with np.load(path) as data:
        missing = [key for key in ("ReS", "ImS") if key not in data.files]
        if missing:
            raise ValueError(f"IMPI_INTERNAL_REBUILD requires {missing} in {path}")
        re_sigma = np.asarray(data["ReS"], dtype=float)
        im_sigma = np.asarray(data["ImS"], dtype=float)
        sigma0 = float(data["sigma0"]) if "sigma0" in data.files else 0.0
        eta = float(data["eta"]) if "eta" in data.files else 1.0e-3
    return re_sigma, im_sigma, sigma0, eta


def _rebuild_a_bilinear(
    k_query: np.ndarray,
    w_query: np.ndarray,
    k_axis: np.ndarray,
    w_axis: np.ndarray,
    re_sigma: np.ndarray,
    im_sigma: np.ndarray,
    *,
    mu: float,
    sigma0: float,
    eta: float,
) -> tuple[np.ndarray, np.ndarray]:
    re_i, re_support = bilinear_eval_with_support(
        k_query, w_query, k_axis, w_axis, re_sigma
    )
    im_i, im_support = bilinear_eval_with_support(
        k_query, w_query, k_axis, w_axis, im_sigma
    )
    support = np.asarray(re_support, dtype=bool) & np.asarray(im_support, dtype=bool)
    xi = np.asarray(k_query, dtype=float) ** 2 - float(mu)
    gamma = np.abs(im_i) + float(eta)
    rebuilt = (1.0 / np.pi) * gamma / (
        (np.asarray(w_query, dtype=float) - xi - (re_i - float(sigma0))) ** 2
        + gamma * gamma
    )
    return np.where(support, rebuilt, 0.0), support


def _impi_process_worker(task: tuple[int, float]) -> tuple[int, float, np.ndarray, np.ndarray, np.ndarray]:
    """Process-pool worker for one q row.

    The heavy cube/table arrays live in the fork-inherited global context.  This
    avoids the GIL bottleneck of q-row threads without pickling the large arrays
    for every task.
    """
    iq0, qv = task
    ctx = _IMPI_WORKER_CTX
    kd = np.asarray(ctx["kd"], dtype=float)
    wd = np.asarray(ctx["wd"], dtype=float)
    ad = np.asarray(ctx["ad"], dtype=float)
    re_dn_obj = ctx.get("re_dn", None)
    im_dn_obj = ctx.get("im_dn", None)
    re_dn = None if re_dn_obj is None else np.asarray(re_dn_obj, dtype=float)
    im_dn = None if im_dn_obj is None else np.asarray(im_dn_obj, dtype=float)
    p_grid = np.asarray(ctx["p_grid"], dtype=float)
    omega_grid = np.asarray(ctx["omega_grid"], dtype=float)
    eps_grid = np.asarray(ctx["eps_grid"], dtype=float)
    aup_grid = np.asarray(ctx["aup_grid"], dtype=float)
    inline_control = bool(ctx.get("inline_control", False))
    control_up_grid_obj = ctx.get("control_up_grid", None)
    control_up_grid = (
        None
        if control_up_grid_obj is None
        else np.asarray(control_up_grid_obj, dtype=float)
    )
    control_kd_obj = ctx.get("control_kd", None)
    control_wd_obj = ctx.get("control_wd", None)
    control_ad_obj = ctx.get("control_ad", None)
    control_kd = None if control_kd_obj is None else np.asarray(control_kd_obj, dtype=float)
    control_wd = None if control_wd_obj is None else np.asarray(control_wd_obj, dtype=float)
    control_ad = None if control_ad_obj is None else np.asarray(control_ad_obj, dtype=float)
    angular_mode = str(ctx["angular_mode"])

    if angular_mode in {"kjac", "phipanel"}:
        _kf_feats = ctx.get("kquad_kf_features", None)
        if angular_mode == "phipanel":
            geom_cache = build_phipanel_geometry_cache(
                kd,
                p_grid,
                q_value=float(qv),
                routing=str(ctx["routing"]),
                n_phi_panel=int(ctx["n_kquad"]),
                phi_panel_chunk_size=int(ctx["kquad_chunk_size"]),
                k_features=_kf_feats,
                k_feature_n_local=int(ctx.get("kquad_feature_n_local", 31)),
                k_feature_half_width=float(ctx.get("kquad_feature_half_width", 0.05)),
            )
        else:
            geom_cache = build_kjac_geometry_cache(
                kd,
                p_grid,
                q_value=float(qv),
                routing=str(ctx["routing"]),
                n_kquad=int(ctx["n_kquad"]),
                kquad_chunk_size=int(ctx["kquad_chunk_size"]),
                kquad_kf_features=_kf_feats,
                kquad_feature_n_local=int(ctx.get("kquad_feature_n_local", 11)),
                kquad_feature_half_width=float(ctx.get("kquad_feature_half_width", 0.05)),
            )

        def _slice_provider(io: int, omega_value: float) -> tuple[np.ndarray, np.ndarray]:
            return precompute_kjac_integrated_slice(
                kd,
                wd,
                ad,
                p_grid,
                eps_grid,
                q_value=float(qv),
                omega_value=float(omega_value),
                routing=str(ctx["routing"]),
                n_kquad=int(ctx["n_kquad"]),
                kquad_chunk_size=int(ctx["kquad_chunk_size"]),
                geom_cache=geom_cache,
                re_sigma=re_dn,
                im_sigma=im_dn,
                sigma0=float(ctx.get("sigma0_dn", 0.0)),
                mu=float(ctx.get("mu_dn", 0.0)),
                eta=float(ctx.get("eta_dn", 1.0e-3)),
            )

        def _control_slice_provider(io: int, omega_value: float) -> tuple[np.ndarray, np.ndarray]:
            if control_kd is None or control_wd is None or control_ad is None:
                raise RuntimeError("inline control arrays are unavailable in worker")
            return precompute_kjac_integrated_slice(
                control_kd,
                control_wd,
                control_ad,
                p_grid,
                eps_grid,
                q_value=float(qv),
                omega_value=float(omega_value),
                routing=str(ctx["routing"]),
                n_kquad=int(ctx["n_kquad"]),
                kquad_chunk_size=int(ctx["kquad_chunk_size"]),
                geom_cache=geom_cache,
            )

        _p_int_mode = str(ctx.get("p_integration_mode", "plain"))
        _p_gl_n = int(ctx.get("p_gl_n", 8))
        _p_split: np.ndarray | None = None
        if _p_int_mode == "panel_kinks":
            # Use FREE kF (sqrt(mu)) so both full and QP runs use identical split
            # points regardless of their interacting kF, keeping analytic_cv
            # subtraction well-conditioned.
            _kf_up = float(np.sqrt(max(float(ctx["mu_up"]), 0.0)))
            _kf_dn = float(np.sqrt(max(float(ctx["mu_dn"]), 0.0)))
            _p_nest = _kf_up - float(qv)  # shifts with Q; negative → outside [0, p_max]
            _candidates = [_kf_dn]
            if _p_nest > float(p_grid[0]):
                _candidates.append(_p_nest)
            _p_split = np.array(_candidates, dtype=float)
        if inline_control:
            if control_up_grid is None:
                raise RuntimeError("inline control up grid is unavailable in worker")
            scan, support_mean_i = _compute_inline_control_scan(
                omega_grid,
                p_grid,
                eps_grid,
                aup_grid,
                control_up_grid,
                _slice_provider,
                _control_slice_provider,
                eps_integration_mode=str(ctx["eps_integration_mode"]),
                p_integration_mode=_p_int_mode,
                p_split_points=_p_split,
                p_gl_n=_p_gl_n,
            )
        else:
            scan, support_mean_i = compute_impi_scan_from_slice_provider(
                omega_grid,
                p_grid,
                eps_grid,
                aup_grid,
                _slice_provider,
                eps_integration_mode=str(ctx["eps_integration_mode"]),
                p_integration_mode=_p_int_mode,
                p_split_points=_p_split,
                p_gl_n=_p_gl_n,
                progress=False,
            )
    else:
        phi_grid = np.asarray(ctx["phi_grid"], dtype=float)
        adn_phi_table, support_frac_table = precompute_phi_integrated_table(
            kd,
            wd,
            ad,
            p_grid,
            omega_grid,
            eps_grid,
            phi_grid,
            q_value=float(qv),
            routing=str(ctx["routing"]),
            phi_chunk_size=int(ctx["phi_chunk_size"]),
            progress=False,
        )
        if inline_control:
            if control_kd is None or control_wd is None or control_ad is None or control_up_grid is None:
                raise RuntimeError("inline control arrays are unavailable in worker")
            control_phi_table, _ = precompute_phi_integrated_table(
                control_kd,
                control_wd,
                control_ad,
                p_grid,
                omega_grid,
                eps_grid,
                phi_grid,
                q_value=float(qv),
                routing=str(ctx["routing"]),
                phi_chunk_size=int(ctx["phi_chunk_size"]),
                progress=False,
            )
            product_residual = (
                aup_grid[None, :, :] * adn_phi_table
                - control_up_grid[None, :, :] * control_phi_table
            )
            scan, support_mean_i = compute_impi_scan_from_table_vectorized(
                omega_grid,
                p_grid,
                eps_grid,
                np.ones_like(aup_grid),
                product_residual,
                support_frac_table,
            )
            del control_phi_table
        else:
            scan, support_mean_i = compute_impi_scan_from_table_vectorized(
                omega_grid,
                p_grid,
                eps_grid,
                aup_grid,
                adn_phi_table,
                support_frac_table,
            )
        del adn_phi_table, support_frac_table

    return (
        int(iq0),
        float(support_mean_i),
        np.asarray(scan["im_pi_thermal"], dtype=float),
        np.asarray(scan["im_pi_med"], dtype=float),
        np.asarray(scan["im_pi_no_thermal"], dtype=float),
    )


